 if($a==='sale'){allow(['ADMIN','STAFF CABANG']);$lid=(int)$_POST['laptop_id'];$pdo->beginTransaction();$l=$pdo->query("SELECT * FROM laptop_units WHERE id=$lid FOR UPDATE")->fetch();if(!$l||$l['status']!=='Tersedia'){ $pdo->rollBack();go('index.php?page=pos','Unit tidak tersedia.');}$phone=trim($_POST['phone']);$st=$pdo->prepare('SELECT id FROM customers WHERE phone=? LIMIT 1');$st->execute([$phone]);$cid=$st->fetchColumn();if(!$cid){$pdo->prepare('INSERT INTO customers(name,phone,address,first_transaction_date) VALUES(?,?,?,CURDATE())')->execute([$_POST['customer_name'],$phone,$_POST['address']]);$cid=$pdo->lastInsertId();}$inv='INV-'.date('Ymd').'-'.str_pad((string)(random_int(1,9999)),4,'0',STR_PAD_LEFT);$pdo->prepare('INSERT INTO transactions(invoice_no,transaction_date,user_id,customer_id,payment_method,total,notes,status) VALUES(?,NOW(),?,?,?,?,?,?)')->execute([$inv,$_SESSION['user']['id'],$cid,$_POST['payment_method'],$l['sale_price'],$_POST['notes'],'Selesai']);$tid=$pdo->lastInsertId();$pdo->prepare('INSERT INTO transaction_details(transaction_id,laptop_id,price,quantity,subtotal) VALUES(?,?,?,1,?)')->execute([$tid,$lid,$l['sale_price'],$l['sale_price']]);$pdo->prepare("UPDATE laptop_units SET status='Terjual' WHERE id=?")->execute([$lid]);$pdo->prepare("INSERT INTO warranties(transaction_id,laptop_id,start_date,end_date,status) VALUES(?,?,CURDATE(),DATE_ADD(CURDATE(),INTERVAL 1 MONTH),'Aktif')")->execute([$tid,$lid]);$pdo->commit();go('index.php?page=transaction_detail&id='.$tid,'Transaksi berhasil. Warranty 1 bulan otomatis dibuat.');}
