 if($a==='save_user'){allow(['ADMIN']);$hash=password_hash($_POST['password'],PASSWORD_DEFAULT);$pdo->prepare('INSERT INTO users(role_id,name,username,password,status) VALUES(?,?,?,?,?)')->execute([(int)$_POST['role_id'],$_POST['name'],$_POST['username'],$hash,$_POST['status']]);go('index.php?page=users','User berhasil dibuat.');}
