<?php elseif($page==='activity'): allow(['ADMIN','OWNER']);$rows=$pdo->query("SELECT a.*,u.name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.id DESC LIMIT 100")->fetchAll();?><div class="page-head"><div><h3>Activity Log</h3><p>Jejak aktivitas penting pengguna sistem.</p></div></div><div class="table-card"><div class="table-responsive"><table class="table modern-table"><thead><tr><th>Waktu</th><th>Pengguna</th><th>Aksi</th><th>Keterangan</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['name']??'Sistem')?></td><td><span class="status-pill"><?=e($r['action'])?></span></td><td><?=e($r['description'])?></td></tr><?php endforeach?></tbody></table></div></div>
<?php elseif($page==='profile'):?><h3 class="fw-bold">Profile</h3><div class="table-card"><h4><?=e($_SESSION['user']['name'])?></h4><p>Username: <?=e($_SESSION['user']['username'])?></p><p>Role: <?=e(role())?></p></div><?php endif?></main><script src="assets/js/app.js"></script></body></html>